#include <cstdlib>
#include <fstream>
#include <iostream>
#include <queue>
#include <string>
#include <vector>
using namespace std;

// Shortest path over legal configurations independently checks all small cases.
long long shortestByBfs(int n) {
    vector<int> powers(n + 1, 1);
    for (int i = 1; i <= n; ++i) powers[i] = powers[i - 1] * 3;
    int target = 0;
    for (int i = 0; i < n; ++i) target += 2 * powers[i];
    vector<int> distance(powers[n], -1);
    queue<int> pending;
    distance[0] = 0;
    pending.push(0);
    while (!pending.empty()) {
        int state = pending.front(); pending.pop();
        if (state == target) return distance[state];
        int top[3] = {n, n, n};
        int digits = state;
        for (int disk = 0; disk < n; ++disk) {
            int peg = digits % 3;
            digits /= 3;
            if (top[peg] == n) top[peg] = disk;
        }
        for (int from = 0; from < 3; ++from) {
            int to = (from + 1) % 3;
            int disk = top[from];
            if (disk == n || top[to] < disk) continue;
            int next = state + (to - from) * powers[disk];
            if (distance[next] < 0) {
                distance[next] = distance[state] + 1;
                pending.push(next);
            }
        }
    }
    return -1;
}

long long expectedBySubproblems(int n) {
    long long forward = 0, backward = 0;
    for (int disks = 1; disks <= n; ++disks) {
        long long nextForward = 2 * backward + 1;
        long long nextBackward = 2 * backward + forward + 2;
        forward = nextForward;
        backward = nextBackward;
    }
    return backward;
}

int main(int argc, char *argv[]) {
    if (argc != 2) { cerr << "Usage: tester <student_executable>\n"; return 2; }
    string exe = argv[1];
    int failed = 0;
    for (int n = 1; n <= 20; ++n) {
        long long expected = expectedBySubproblems(n);
        if (n <= 7 && shortestByBfs(n) != expected) {
            cerr << "Internal oracle disagreement at n=" << n << '\n';
            return 2;
        }
        ofstream input("hanoi_test.in");
        input << n << '\n'; input.close();
        int status = system(("\"" + exe + "\" < hanoi_test.in > hanoi_test.out 2>&1").c_str());
        ifstream output("hanoi_test.out");
        long long actual = -1;
        string extra;
        bool valid = bool(output >> actual) && !(output >> extra);
        if (status != 0 || !valid || actual != expected) {
            cout << "[FAIL] n=" << n << "\nInput: " << n << "\nExpected: "
                 << expected << "\nActual: ";
            ifstream raw("hanoi_test.out");
            cout << raw.rdbuf() << '\n';
            ++failed;
        }
    }
    cout << "Hanoi: " << 20 - failed << "/20 cases passed\n";
    return failed ? 1 : 0;
}

